// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    function testFuzz_property(address from, address recipient, uint256 amount) public {
        address[] memory tos = new address[](1);
        tos[0] = recipient;
        uint256[] memory vals = new uint256[](1);
        vals[0] = amount;

        RecordingCallee rec = new RecordingCallee();
        c.transfer(from, address(rec), tos, vals);

        // The callee must have been called exactly once.
        assertTrue(rec.callCount() == 1);

        // The call must use the transferFrom(address,address,uint256) selector.
        assertTrue(rec.lastSelector() == bytes4(keccak256("transferFrom(address,address,uint256)")));

        // The first decoded argument (the "from" in transferFrom) must equal the caller-supplied from.
        // In the mutant, the call is transfer(address,uint256), so the first decoded argument
        // would be the recipient address (the callee would see recipient as the spender/from).
        assertTrue(rec.lastFrom() == from);
    }
}

contract RecordingCallee {
    uint256 public callCount;
    bytes4 public lastSelector;
    address public lastFrom;

    function transferFrom(address from, address, uint256) external payable {
        callCount++;
        lastSelector = msg.sig;
        lastFrom = from;
    }

    fallback() external payable {
        callCount++;
        lastSelector = msg.sig;
        if (msg.data.length >= 36) {
            address from;
            assembly {
                from := calldataload(4)
            }
            lastFrom = from;
        }
    }
}
